    "static/style.css",
    '/*\n * Contrast ratios (WCAG 2.1; AA asks 4.5:1 for text):\n *\n *               on --bg   on --surface\n *   light\n *     --text     15.81     14.22\n *     --muted     6.25      5.63\n *     --accent    6.28      5.65\n *     --warning   6.39      5.75\n *   dark\n *     --text     13.84     11.96\n *     --muted     7.36      6.36\n *     --accent    8.63      7.46\n *     --warning   8.52      7.36\n *\n * Recompute them after changing a colour.\n */\n:root {\n  color-scheme: light dark;\n  --bg: #fbfaf7;\n  --surface: #f0eee8;\n  --text: #1d1f23;\n  --muted: #595e66;\n  --accent: #245f9e;\n  --warning: #8f4a00;\n  --measure: 42rem;\n  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;\n  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #16181c;\n    --surface: #22252b;\n    --text: #e4e3df;\n    --muted: #a2a7b0;\n    --accent: #8ab8f0;\n    --warning: #e9a65a;\n  }\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  @view-transition {\n    navigation: auto;\n  }\n}\n\n/* Page */\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  max-width: var(--measure);\n  margin: 0 auto;\n  padding: 0 1.25rem;\n  background: var(--bg);\n  color: var(--text);\n  font: 1.125rem / 1.65 var(--sans);\n  overflow-wrap: break-word;\n}\n\na {\n  color: var(--accent);\n  text-underline-offset: 0.15em;\n}\n\n:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\n.skip-link {\n  position: absolute;\n  left: 1rem;\n  top: -10rem;\n  padding: 0.5rem 1rem;\n  background: var(--surface);\n}\n\n.skip-link:focus {\n  top: 1rem;\n}\n\n.site-header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 0.5rem 1.5rem;\n  padding: 2rem 0;\n}\n\n.site-title {\n  color: var(--text);\n  font-weight: 700;\n  text-decoration: none;\n}\n\n.site-header ul {\n  display: flex;\n  gap: 1.25rem;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.site-footer {\n  margin-top: 4rem;\n  padding: 1.5rem 0 3rem;\n  border-top: 1px solid var(--surface);\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n.site-footer p {\n  margin: 0.25rem 0;\n}\n\n/* Text */\n\nh1,\nh2,\nh3 {\n  line-height: 1.25;\n  text-wrap: balance;\n}\n\nh1 {\n  font-size: 2rem;\n  margin: 0 0 0.5rem;\n}\n\nh2 {\n  font-size: 1.4rem;\n  margin: 2.5rem 0 0.75rem;\n}\n\nimg,\npicture,\nsvg,\nvideo {\n  max-width: 100%;\n  height: auto;\n}\n\nblockquote {\n  margin: 1.5rem 0;\n  padding-left: 1.25rem;\n  border-left: 3px solid var(--surface);\n  color: var(--muted);\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  padding: 0.4rem 0.6rem;\n  border-bottom: 1px solid var(--surface);\n  text-align: left;\n}\n\n/* Code */\n\ncode,\npre {\n  font-family: var(--mono);\n  font-size: 0.9em;\n}\n\n:not(pre) > code {\n  padding: 0.1em 0.3em;\n  border-radius: 4px;\n  background: var(--surface);\n}\n\npre {\n  padding: 1rem 1.25rem;\n  overflow-x: auto;\n  border-radius: 6px;\n  line-height: 1.5;\n}\n\n/* Shiki\'s documented CSS for dark themes; the light ones are inline. */\n@media (prefers-color-scheme: dark) {\n  /* Shiki sets the light colours inline, which only !important overrides. */\n  .shiki,\n  .shiki span {\n    color: var(--shiki-dark) !important;\n    background-color: var(--shiki-dark-bg) !important;\n    font-style: var(--shiki-dark-font-style) !important;\n    font-weight: var(--shiki-dark-font-weight) !important;\n    text-decoration: var(--shiki-dark-text-decoration) !important;\n  }\n}\n\n/* Posts */\n\n.byline {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.25rem 1rem;\n  margin: 0 0 2rem;\n  color: var(--muted);\n  font-size: 0.95rem;\n}\n\n.post-list,\n.archive,\n.tag-index {\n  padding: 0;\n  list-style: none;\n}\n\n.post-list li {\n  margin-bottom: 2rem;\n}\n\n.post-list h2 {\n  margin: 0;\n}\n\n.post-list time,\n.archive time {\n  color: var(--muted);\n  font-size: 0.95rem;\n}\n\n.post-list p {\n  margin: 0.25rem 0 0;\n}\n\n.archive li {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0 1rem;\n  margin-bottom: 0.5rem;\n}\n\n.archive time {\n  min-width: 10rem;\n}\n\n.pagination {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 2rem;\n}\n\n.callout {\n  margin: 1.5rem 0;\n  padding: 0.75rem 1.25rem;\n  border-left: 4px solid var(--accent);\n  border-radius: 4px;\n  background: var(--surface);\n}\n\n.callout.warning {\n  border-left-color: var(--warning);\n}\n\n.callout-label {\n  margin: 0;\n}\n\n.callout.warning .callout-label {\n  color: var(--warning);\n}\n',
